import{_ as r,c as a,o as e,ag as i}from"./chunks/framework.CMajxlqO.js";const m=JSON.parse('{"title":"Jämförelse med Mitsubishi GX Works 2","description":"","frontmatter":{},"headers":[],"relativePath":"01-introduktion/jamforelse-gx-works.md","filePath":"01-introduktion/jamforelse-gx-works.md","lastUpdated":1768315788000}'),n={name:"01-introduktion/jamforelse-gx-works.md"};function o(s,t,l,d,g,u){return e(),a("div",null,[...t[0]||(t[0]=[i('<h1 id="jamforelse-med-mitsubishi-gx-works-2" tabindex="-1">Jämförelse med Mitsubishi GX Works 2 <a class="header-anchor" href="#jamforelse-med-mitsubishi-gx-works-2" aria-label="Permalink to &quot;Jämförelse med Mitsubishi GX Works 2&quot;">​</a></h1><p>Om du har erfarenhet av Mitsubishi GX Works 2 kommer du att känna igen många koncept i TIA Portal, men det finns också viktiga skillnader i hur systemen fungerar och är strukturerade. Denna jämförelse hjälper dig att förstå likheter och anpassa dig till TIA Portal.</p><h2 id="oversikt-grundlaggande-likheter" tabindex="-1">Översikt: Grundläggande likheter <a class="header-anchor" href="#oversikt-grundlaggande-likheter" aria-label="Permalink to &quot;Översikt: Grundläggande likheter&quot;">​</a></h2><p>Både TIA Portal och GX Works 2 är integrerade utvecklingsmiljöer för industriell automation:</p><ul><li>Båda erbjuder PLC-programmering, HMI-design och nätverkskonfiguration</li><li>Stöd för flera programmeringsspråk (LAD, FBD, ST/SCL)</li><li>Projektbaserad struktur med centraliserad datahållning</li><li>Simuleringsmöjligheter för testning</li></ul><h2 id="huvudsakliga-skillnader" tabindex="-1">Huvudsakliga skillnader <a class="header-anchor" href="#huvudsakliga-skillnader" aria-label="Permalink to &quot;Huvudsakliga skillnader&quot;">​</a></h2><h3 id="_1-anvandargranssnitt-och-arbetsflode" tabindex="-1">1. Användargränssnitt och arbetsflöde <a class="header-anchor" href="#_1-anvandargranssnitt-och-arbetsflode" aria-label="Permalink to &quot;1. Användargränssnitt och arbetsflöde&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Aspekt</th><th>TIA Portal</th><th>GX Works 2</th></tr></thead><tbody><tr><td><strong>Projektvy</strong></td><td>Träd-struktur till vänster, arbetsyta till höger</td><td>Flik-baserat gränssnitt</td></tr><tr><td><strong>Navigation</strong></td><td>Portal-vy med kategorier (PLC, HMI, Network)</td><td>Projekt-navigator och separata verktyg</td></tr><tr><td><strong>Multitasking</strong></td><td>Flera editorer kan vara öppna samtidigt</td><td>En huvudvy i taget</td></tr><tr><td><strong>Integration</strong></td><td>HMI-design inbyggd i samma miljö</td><td>GT Designer separat verktyg</td></tr></tbody></table><h3 id="_2-programmeringsstruktur" tabindex="-1">2. Programmeringsstruktur <a class="header-anchor" href="#_2-programmeringsstruktur" aria-label="Permalink to &quot;2. Programmeringsstruktur&quot;">​</a></h3><p><strong>TIA Portal / SIMATIC:</strong></p><ul><li><strong>Organization Blocks (OB)</strong> - Huvudprogram och händelser</li><li><strong>Function Blocks (FB)</strong> - Med instans-databas</li><li><strong>Functions (FC)</strong> - Återanvändbara funktioner utan minnesområde</li><li><strong>Data Blocks (DB)</strong> - Strukturerad datalagring</li></ul><p><strong>GX Works 2 / Mitsubishi:</strong></p><ul><li><strong>Main Program</strong> - Huvudprogram</li><li><strong>Subroutines (SUB)</strong> - Återanvändbara program</li><li><strong>Function Blocks (FB)</strong> - Liknande som Siemens men annan struktur</li><li><strong>Device Memory</strong> - D-register, M-relä, etc.</li></ul><div class="tip custom-block"><p class="custom-block-title">Viktigt att notera</p><p>I TIA Portal måste du skapa en instans (DB) för varje FB du använder. I GX Works 2 hanteras detta annorlunda med direkta minnesområden.</p></div><h3 id="_3-adressering-och-taggar" tabindex="-1">3. Adressering och taggar <a class="header-anchor" href="#_3-adressering-och-taggar" aria-label="Permalink to &quot;3. Adressering och taggar&quot;">​</a></h3><p><strong>TIA Portal:</strong></p><ul><li>Använder <strong>symboliska namn</strong> (taggar) som standard</li><li>Exempel: <code>Motor_Start</code>, <code>Sensor_Temperature</code></li><li>Absolut adressering: <code>%I0.0</code>, <code>%Q1.3</code>, <code>%MW10</code></li><li>Taggtabeller hanterar både namn och adresser</li></ul><p><strong>GX Works 2:</strong></p><ul><li>Primärt <strong>direkt adressering</strong></li><li>Exempel: <code>X0</code>, <code>Y10</code>, <code>D100</code>, <code>M0</code></li><li>Kommentarer och etiketter som tillägg</li><li>Global Device Comments för symbolhantering</li></ul><h3 id="_4-datatyper" tabindex="-1">4. Datatyper <a class="header-anchor" href="#_4-datatyper" aria-label="Permalink to &quot;4. Datatyper&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Datatyp</th><th>TIA Portal</th><th>GX Works 2</th></tr></thead><tbody><tr><td>Bit</td><td>BOOL</td><td>Bit Device (X, Y, M)</td></tr><tr><td>Byte</td><td>BYTE (8 bit)</td><td>-</td></tr><tr><td>Word</td><td>WORD (16 bit)</td><td>Word (D, W)</td></tr><tr><td>Double Word</td><td>DWORD (32 bit)</td><td>Double Word (D+1)</td></tr><tr><td>Integer</td><td>INT, DINT</td><td>K (decimal), H (hex)</td></tr><tr><td>Real</td><td>REAL</td><td>E (scientific notation)</td></tr><tr><td>String</td><td>STRING</td><td>String (Special FB)</td></tr></tbody></table><h3 id="_5-kommunikation-och-natverk" tabindex="-1">5. Kommunikation och nätverk <a class="header-anchor" href="#_5-kommunikation-och-natverk" aria-label="Permalink to &quot;5. Kommunikation och nätverk&quot;">​</a></h3><p><strong>TIA Portal:</strong></p><ul><li><strong>Profinet</strong> som primär standard</li><li>Grafisk nätverkskonfiguration i Portal</li><li>Automatisk konfiguration av telegramstrukturer</li><li>OPC UA-stöd inbyggt</li></ul><p><strong>GX Works 2:</strong></p><ul><li><strong>CC-Link</strong> och <strong>CC-Link IE</strong> primärt</li><li>Ethernet-kommunikation (MC Protocol)</li><li>Nätverkskonfiguration via separata verktyg</li><li>Modbus RTU/TCP-stöd</li></ul><h3 id="_6-hmi-integration" tabindex="-1">6. HMI-integration <a class="header-anchor" href="#_6-hmi-integration" aria-label="Permalink to &quot;6. HMI-integration&quot;">​</a></h3><p><strong>TIA Portal (WinCC):</strong></p><ul><li>Integrerad i samma projekt</li><li>Taggar delas automatiskt mellan PLC och HMI</li><li>Enkel drag-and-drop från PLC till HMI</li><li>Konsekvent projekthantering</li></ul><p><strong>GX Works 2 (GT Designer3):</strong></p><ul><li>Separat verktyg (GT Designer3)</li><li>Export/import av devicelistor</li><li>Manuell synkronisering mellan projekt</li><li>Separata projektfiler</li></ul><h2 id="migreringstips-fran-gx-works-2-till-tia-portal" tabindex="-1">Migreringstips: Från GX Works 2 till TIA Portal <a class="header-anchor" href="#migreringstips-fran-gx-works-2-till-tia-portal" aria-label="Permalink to &quot;Migreringstips: Från GX Works 2 till TIA Portal&quot;">​</a></h2><p>Om du kommer från Mitsubishi-världen:</p><ol><li><strong>Lär dig tänka i taggar</strong> - Använd symboliska namn istället för absoluta adresser</li><li><strong>Förstå FB-instanser</strong> - Varje FB behöver ett DB (instans-databas)</li><li><strong>Utforska projektstrukturen tidigt</strong> - Portal-vyn är din vän</li><li><strong>Använd Auto-Hotkeys</strong> - TIA Portal har många tangentbordsgenvägar</li><li><strong>Läs Programming Guideline</strong> - Siemens best practices skiljer sig från Mitsubishi</li></ol><h3 id="vanliga-gotchas" tabindex="-1">Vanliga &quot;gotchas&quot; <a class="header-anchor" href="#vanliga-gotchas" aria-label="Permalink to &quot;Vanliga &quot;gotchas&quot;&quot;">​</a></h3><ul><li><strong>Ingen M-relay direkt</strong> - Använd <code>%M</code> (Memory bits) eller taggar</li><li><strong>OB1 är inte Main</strong> - Det är en cyklisk organisation block</li><li><strong>Data Blocks krävs</strong> - För FB-instanser och strukturerad data</li><li><strong>Kompilera ofta</strong> - TIA Portal kräver kompilering för vissa funktioner</li></ul><h2 id="sammanfattning" tabindex="-1">Sammanfattning <a class="header-anchor" href="#sammanfattning" aria-label="Permalink to &quot;Sammanfattning&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Kriteria</th><th>TIA Portal</th><th>GX Works 2</th></tr></thead><tbody><tr><td><strong>Inlärningskurva</strong></td><td>Medel-Hög</td><td>Medel</td></tr><tr><td><strong>HMI-integration</strong></td><td>Utmärkt (inbyggd)</td><td>Bra (separat)</td></tr><tr><td><strong>Dokumentation</strong></td><td>Omfattande</td><td>Omfattande</td></tr><tr><td><strong>Global spridning</strong></td><td>Mycket stor (Europa)</td><td>Stor (Asien)</td></tr><tr><td><strong>Pris</strong></td><td>Medel-Högt</td><td>Medel</td></tr></tbody></table><h2 id="resurser-for-migrering" tabindex="-1">Resurser för migrering <a class="header-anchor" href="#resurser-for-migrering" aria-label="Permalink to &quot;Resurser för migrering&quot;">​</a></h2><ul><li><a href="https://support.industry.siemens.com/cs/ww/en/view/86630375" target="_blank" rel="noreferrer">Siemens vs Mitsubishi Comparison Guide</a> - Officiell jämförelse</li><li>Sök på YouTube: &quot;TIA Portal for Mitsubishi users&quot;</li><li>Forum: <a href="https://support.industry.siemens.com/forum/ww/en" target="_blank" rel="noreferrer">Siemens Industry Support Forum</a></li></ul><div class="info custom-block"><p class="custom-block-title">För erfarnade GX Works 2-användare</p><p>Det tar vanligtvis 2-4 veckor att känna sig bekväm med TIA Portal om du har god erfarenhet av GX Works 2. Koncepten är liknande, men verktygen och arbetsflödet kräver viss anpassning.</p></div>',41)])])}const h=r(n,[["render",o]]);export{m as __pageData,h as default};
